const input = $input.first().json;
const body = input.body || input;
const value = body.entry?.[0]?.changes?.[0]?.value;
if (value?.statuses && !value?.messages) return [];
const msg = value?.messages?.[0];
const contact = value?.contacts?.[0];
if (!msg) return [];
let message = '', mediaId = '', mediaType = '', latitude = null, longitude = null;
if (msg.type === 'text') message = msg.text?.body || '';
else if (msg.type === 'location') {
  latitude = msg.location?.latitude ?? null;
  longitude = msg.location?.longitude ?? null;
  message = `ubicacion: ${latitude}, ${longitude}`;
} else if (msg.type === 'image') {
  mediaId = msg.image?.id || '';
  mediaType = 'image';
  message = msg.image?.caption || '[imagen recibida]';
} else if (msg.type === 'document') {
  mediaId = msg.document?.id || '';
  mediaType = 'document';
  message = msg.document?.caption || msg.document?.filename || '[documento recibido]';
} else if (msg.type === 'interactive') {
  message = msg.interactive?.button_reply?.title || msg.interactive?.button_reply?.id || msg.interactive?.list_reply?.title || msg.interactive?.list_reply?.id || '';
} else message = `[${msg.type || 'archivo'} recibido]`;
const from = String(msg.from || '').replace(/\D/g, '');
const userName = contact?.profile?.name || 'Usuario Forestal';
const conversationId = `whatsapp:${from}`;
const incomingMessageId = msg.id || `${conversationId}:${message}:${Math.floor(Date.now() / 5000)}`;
try {
  const staticData = $getWorkflowStaticData('global');
  staticData.processedMessages = staticData.processedMessages || {};
  if (staticData.processedMessages[incomingMessageId]) return [];
  staticData.processedMessages[incomingMessageId] = new Date().toISOString();
  const ids = Object.keys(staticData.processedMessages);
  if (ids.length > 1000) for (const id of ids.slice(0, ids.length - 1000)) delete staticData.processedMessages[id];
} catch(e) {}
if (!message || !from) return [];
return [{json:{channel:'whatsapp', from, userName, message:String(message).trim(), conversationId, incomingMessageId, mediaId, mediaType, latitude, longitude, timestamp:new Date().toISOString(), raw: 'SANITIZED_FOR_GITHUB'}}];

const input = $input.first().json;
const now = Date.now();
const WINDOW_MS = 60000;
const MAX_MESSAGES = Number($env.RATE_LIMIT_PER_MINUTE || 15);
try {
  const staticData = $getWorkflowStaticData('global');
  staticData.rateLimiter = staticData.rateLimiter || {};
  const key = `rate:${input.conversationId}`;
  const item = staticData.rateLimiter[key] || { timestamps: [] };
  item.timestamps = (item.timestamps || []).filter(t => now - t < WINDOW_MS);
  if (item.timestamps.length >= MAX_MESSAGES) {
    staticData.rateLimiter[key] = item;
    return [{json:{...input, rateLimited:true, finalMessage:'Estoy recibiendo muchos mensajes seguidos. Espera unos segundos y vuelve a intentarlo, por favor.'}}];
  }
  item.timestamps.push(now);
  staticData.rateLimiter[key] = item;
} catch(e) {}
return [{json:{...input, rateLimited:false}}];

// Si ya fue procesado por la rama legal, salir
if ($input.first().json.procesado_legal === true) {
  return [];
}

const input = $input.first().json;
const original = $('Rate Limiter').first().json;

const text = input.candidates?.[0]?.content?.parts?.[0]?.text || '';

let data = {};

try {
  const clean = text.replace(/```json/gi, '').replace(/```/g, '').trim();
  const match = clean.match(/\{[\s\S]*\}/);
  data = JSON.parse(match ? match[0] : clean);
} catch (e) {
  data = {
    tipo: 'OTRO',
    prioridad: 'BAJA',
    crear_caso: false,
    descripcion: original.message,
    coordenadas: {
      lat: original.latitude,
      lon: original.longitude
    },
    requiere_foto: false,
    requiere_coordenadas: false,
    requiere_escalado: false,
    respuesta_usuario: 'He recibido tu mensaje, pero necesito más detalles para clasificarlo correctamente.'
  };
}

const tiposValidos = [
  'INCENDIO',
  'PLAGA',
  'PERMISO',
  'INCIDENCIA',
  'CONSULTA_NORMATIVA',
  'PARTE_TRABAJO',
  'OTRO'
];

if (!tiposValidos.includes(data.tipo)) {
  data.tipo = 'OTRO';
}

if (!['ALTA', 'MEDIA', 'BAJA'].includes(data.prioridad)) {
  data.prioridad = 'MEDIA';
}

// Si WhatsApp recibió ubicación nativa, tiene prioridad sobre Gemini
if (original.latitude !== null && original.longitude !== null) {
  data.coordenadas = {
    lat: original.latitude,
    lon: original.longitude
  };
}

const lat = data.coordenadas?.lat ?? null;
const lon = data.coordenadas?.lon ?? null;

// Crear caso
let crearCaso = data.crear_caso !== false;

// Seguridad extra: saludos/casuales no crean caso aunque Gemini falle
const mensajeLimpio = String(original.message || '').trim().toLowerCase();

const mensajesCasuales = [
  'hola',
  'buenas',
  'buenos dias',
  'buenos días',
  'buenas tardes',
  'buenas noches',
  'gracias',
  'ok',
  'vale',
  'perfecto',
  'adios',
  'adiós'
];

if (data.tipo === 'OTRO' && mensajesCasuales.includes(mensajeLimpio)) {
  crearCaso = false;
  data.prioridad = 'BAJA';
  data.requiere_foto = false;
  data.requiere_coordenadas = false;
  data.requiere_escalado = false;
}

// Coordenadas necesarias
const needsCoords =
  crearCaso === true &&
  ['INCENDIO', 'PLAGA', 'PERMISO', 'INCIDENCIA'].includes(data.tipo) &&
  (lat === null || lon === null);

const requiereEscalado =
  crearCaso === true &&
  (
    data.requiere_escalado === true ||
    data.prioridad === 'ALTA' ||
    data.tipo === 'INCENDIO'
  );

let finalMessage =
  data.respuesta_usuario ||
  'He registrado tu mensaje.';

if (needsCoords) {
  finalMessage = `He clasificado tu aviso como *${data.tipo}*.

Para registrarlo correctamente necesito la ubicación exacta. Puedes enviarme la ubicación de WhatsApp o escribir las coordenadas en formato: 40.4168, -3.7038`;
}

return [{
  json: {
    ...original,

    classification: data,

    tipo: data.tipo,
    prioridad: data.prioridad,
    crearCaso,

    descripcion: data.descripcion || original.message,

    lat,
    lon,

    ubicacion_texto: data.ubicacion_texto || null,
    tipo_plaga: data.tipo_plaga || null,
    especie_afectada: data.especie_afectada || null,
    parcela: data.parcela || null,
    permiso_tipo: data.permiso_tipo || null,
    plazo: data.plazo || null,
    horas: data.horas || null,
    tareas: data.tareas || null,

    faltanCoordenadas: needsCoords,
    requiereEscalado,

    finalMessage,

    caseId: crearCaso
      ? `FOR-${Date.now()}-${Math.random().toString(36).slice(2, 7).toUpperCase()}`
      : null
  }
}];

const prepararRegistro = $('Preparar Registro').first().json;
const original = prepararRegistro.original;
const saved = $input.first().json;
const metadata = saved.metadata || {};

// ⚠️ IMPORTANTE: Prioridad TOTAL a original (no a saved)
const from = original.from || saved.reporter_phone || metadata.telefono || '';
const userName = original.userName || saved.reporter_name || metadata.responsable || 'Usuario';
const tipo = original.tipo || saved.incident_type || metadata.tipo || 'No especificado';
const prioridad = original.prioridad || saved.priority || metadata.prioridad || 'No especificada';
const caseId = original.caseId || saved.case_id || metadata.case_id || 'No disponible';
const descripcion = original.descripcion || saved.description || metadata.descripcion || 'Sin descripción';
const lat = original.lat || saved.latitude || metadata.coordenadas_lat || null;
const lon = original.lon || saved.longitude || metadata.coordenadas_lon || null;
const requiereEscalado = original.requiereEscalado || metadata.requiere_escalado || false;
const finalMessage = original.finalMessage || 'Incidente registrado correctamente.';

// La ubicación viene DIRECTAMENTE de original
const ubicacionNombre = original.ubicacion_nombre || null;
const ubicacionLegible = ubicacionNombre || (lat && lon ? `${lat}, ${lon}` : 'Sin coordenadas');
const supervisorNumber = $env.SUPERVISOR_WHATSAPP || 'SUPERVISOR_PHONE';

// Mensaje para el USUARIO (con ID y ubicación)
const userMessage = `${finalMessage}\n\n📋 ID de registro: ${caseId}\n\n📍 *Ubicación:* ${ubicacionLegible}\n\n🌲 Gracias por proteger nuestros bosques.`;

// Mensaje para el SUPERVISOR (con ID y ubicación legible)
const supervisorMessage = `🌲 *AI FOREST ASSISTANT*\n━━━━━━━━━━━━━━━━━━━━\n📌 *NUEVO CASO*\n━━━━━━━━━━━━━━━━━━━━\n🔹 *Tipo:* ${tipo}\n🔹 *Prioridad:* ${prioridad}\n🔹 *ID:* ${caseId}\n🔹 *Ubicación:* ${ubicacionLegible}\n🔹 *Reporta:* ${userName}\n🔹 *Teléfono:* ${from}\n━━━━━━━━━━━━━━━━━━━━\n📝 *Descripción:*\n${descripcion}\n━━━━━━━━━━━━━━━━━━━━\n⚠️ Se requiere atención inmediata.`;

return [{
  json: {
    from: from,
    reporter_phone: from,
    userName: userName,
    tipo: tipo,
    prioridad: prioridad,
    caseId: caseId,
    descripcion: descripcion,
    finalMessage: finalMessage,
    requiereEscalado: requiereEscalado,
    lat: lat,
    lon: lon,
    supabaseResponse: saved,
    supervisorNumber: supervisorNumber,
    supervisorMessage: supervisorMessage,
    shouldNotifySupervisor: requiereEscalado === true && supervisorNumber !== '',
    userMessage: userMessage,
    // Añadir ubicación para el siguiente nodo
    ubicacion_nombre: ubicacionNombre
  }
}];

