const i = $input.first().json;

let table = 'forest_incidents';
let payload = {};

// ============================================
// 1. PERMISO
// ============================================
if (i.tipo === 'PERMISO') {
  table = 'permits';
  payload = {
    permit_type: i.permiso_tipo || null,
    applicant_name: i.userName || null,
    applicant_phone: i.from || null,
    description: i.descripcion || null,
    latitude: (i.lat !== null && i.lat !== undefined) ? i.lat : null,
    longitude: (i.lon !== null && i.lon !== undefined) ? i.lon : null,
    urgency: i.prioridad || null,
    metadata: {
      case_id: i.caseId,
      mensaje_original: i.message,
      ubicacion_texto: i.ubicacion_texto,
      especie: i.especie,
      parcela: i.parcela,
      plazo: i.plazo,
      horas: i.horas,
      tareas: i.tareas,
      requiere_escalado: i.requiereEscalado,
      channel: i.channel
    }
  };
}

// ============================================
// 2. PARTE_TRABAJO
// ============================================
else if (i.tipo === 'PARTE_TRABAJO') {
  table = 'work_reports';
  payload = {
    worker_name: i.userName || null,
    hours_worked: i.horas ? parseFloat(i.horas) : null,
    tasks_completed: i.tareas || null,
    location_text: i.ubicacion_texto || null,
    latitude: (i.lat !== null && i.lat !== undefined) ? i.lat : null,
    longitude: (i.lon !== null && i.lon !== undefined) ? i.lon : null,
    metadata: {
      case_id: i.caseId,
      prioridad: i.prioridad,
      mensaje_original: i.message,
      descripcion: i.descripcion,
      requiere_escalado: i.requiereEscalado,
      channel: i.channel
    }
  };
}

// ============================================
// 3. PLAGA
// ============================================
else if (i.tipo === 'PLAGA') {
  table = 'pest_cases';
  payload = {
    pest_type: i.especie || null,
    description: i.descripcion || null,
    latitude: (i.lat !== null && i.lat !== undefined) ? i.lat : null,
    longitude: (i.lon !== null && i.lon !== undefined) ? i.lon : null,
    severity: i.prioridad || 'MEDIA',
    metadata: {
      case_id: i.caseId,
      mensaje_original: i.message,
      ubicacion_texto: i.ubicacion_texto,
      parcela: i.parcela,
      reporter_name: i.userName,
      reporter_phone: i.from,
      requiere_escalado: i.requiereEscalado,
      channel: i.channel
    }
  };
}

// ============================================
// 4. FOREST_INCIDENTS (INCENDIO, INCIDENCIA, OTRO)
// ============================================
else {
  table = 'forest_incidents';
  payload = {
    incident_type: i.tipo,
    description: i.descripcion || null,
    priority: i.prioridad || 'MEDIA',
    reporter_name: i.userName || null,
    reporter_phone: i.from || null,
    latitude: (i.lat !== null && i.lat !== undefined) ? i.lat : null,
    longitude: (i.lon !== null && i.lon !== undefined) ? i.lon : null,
    case_id: i.caseId || null,
    parcela: i.parcela || null,
    status: 'ABIERTO',
    ai_classification: i.tipo,
    assigned_to: 'Supervisor Forestal',
    metadata: {
      mensaje_original: i.message,
      ubicacion_texto: i.ubicacion_texto,
      especie: i.especie,
      permiso_tipo: i.permiso_tipo,
      plazo: i.plazo,
      horas: i.horas,
      tareas: i.tareas,
      media_id: i.mediaId,
      media_type: i.mediaType,
      requiere_escalado: i.requiereEscalado,
      channel: i.channel,
      conversation_id: i.conversationId
    }
  };
}

// Eliminar campos con valor null o undefined
Object.keys(payload).forEach(key => {
  if (payload[key] === null || payload[key] === undefined) {
    delete payload[key];
  }
});

// Asegurar que metadata siempre exista
if (!payload.metadata && i) {
  payload.metadata = { original_message: i.message };
}

return [{ json: { 
  table, 
  payload, 
  original: {
    ...i,
    ubicacion_nombre: i.ubicacion_nombre,
    ubicacion_completa: i.ubicacion_completa,
    ubicacion_municipio: i.ubicacion_municipio,
    ubicacion_provincia: i.ubicacion_provincia
  }
} }];

const i = $input.first().json;

// Función para validar coordenadas
function validarCoordenadas(lat, lon) {
  // Convertir a número si es string
  const latNum = parseFloat(lat);
  const lonNum = parseFloat(lon);

  // Verificar que son números válidos
  if (isNaN(latNum) || isNaN(lonNum)) {
    return { valida: false, lat: null, lon: null, error: 'No son números' };
  }

  // Rango válido: lat -90 a 90, lon -180 a 180
  if (Math.abs(latNum) > 90) {
    return { valida: false, lat: null, lon: null, error: 'Latitud fuera de rango (-90 a 90)' };
  }

  if (Math.abs(lonNum) > 180) {
    return { valida: false, lat: null, lon: null, error: 'Longitud fuera de rango (-180 a 180)' };
  }

  return { valida: true, lat: latNum, lon: lonNum, error: null };
}

// Obtener coordenadas de diferentes fuentes
let lat = i.lat || i.coordenadas?.lat || i.classification?.coordenadas?.lat || null;
let lon = i.lon || i.coordenadas?.lon || i.classification?.coordenadas?.lon || null;

// Si no hay coordenadas en el objeto principal, buscar en metadata
if ((lat === null || lon === null) && i.metadata) {
  lat = lat || i.metadata.coordenadas_lat || null;
  lon = lon || i.metadata.coordenadas_lon || null;
}

const coords = validarCoordenadas(lat, lon);

// Determinar si necesita coordenadas según el tipo
const tiposQueNecesitanCoords = ['INCENDIO', 'PLAGA', 'PERMISO', 'INCIDENCIA'];
const necesitaCoordenadas = tiposQueNecesitanCoords.includes(i.tipo) && !coords.valida;

// Mensaje para pedir coordenadas si es necesario
let mensajePedirCoordenadas = '';
if (necesitaCoordenadas) {
  mensajePedirCoordenadas = `Para registrar correctamente este *${i.tipo}*, necesito la ubicación exacta.\n\nPuedes enviarme:\n• Ubicación de WhatsApp\n• Coordenadas (ej: 40.4168, -3.7038)\n• Descripción de la zona`;
}

return [{
  json: {
    ...i,
    // Coordenadas validadas
    lat_validada: coords.lat,
    lon_validada: coords.lon,
    coords_validas: coords.valida,
    error_coordenadas: coords.error,
    necesita_coordenadas: necesitaCoordenadas,
    mensaje_pedir_coordenadas: mensajePedirCoordenadas
  }
}];

const i = $input.first().json;

// Mensaje personalizado según el tipo de incidencia
const mensajesPorTipo = {
  'INCENDIO': '🔥 *INCENDIO* - Necesito la ubicación exacta para activar los protocolos de emergencia.',
  'PLAGA': '🐛 *PLAGA* - Para evaluar el alcance, necesito saber dónde está ocurriendo.',
  'PERMISO': '📄 *PERMISO* - La ubicación es obligatoria para tramitar la solicitud.',
  'INCIDENCIA': '⚠️ *INCIDENCIA* - Necesito las coordenadas para registrar correctamente el incidente.'
};

const mensajeTipo = mensajesPorTipo[i.tipo] || 'Para registrar correctamente este aviso, necesito la ubicación exacta.';

const mensajeFinal = `${mensajeTipo}\n\n${i.mensaje_pedir_coordenadas || '📍 Puedes enviarme tu ubicación usando el botón de adjuntar ubicación de WhatsApp, o escribir las coordenadas en formato: 40.4168, -3.7038'}`;

// Actualizar el mensaje final para el usuario
const finalMessage = mensajeFinal;

// Marcar que estamos esperando coordenadas
const waitingForCoords = true;

return [{
  json: {
    ...i,
    finalMessage,
    waitingForCoords,
    whatsappTo: i.from,
    whatsappText: finalMessage
  }
}];

const i = $input.first().json;

// ============================================
// CAPA 1: Contexto base (siempre presente)
// ============================================
const baseContext = `=== NORMATIVA FORESTAL ESPAÑOLA (BASE) ===

**Ley de Montes (Ley 43/2003):**
- Artículo 38: Prohibido fuego sin autorización (junio-septiembre)
- Artículo 45: Talas y podas requieren autorización administrativa previa

**Especies protegidas:** Encina, Alcornoque, Tejo, Roble albar

**Distancias mínimas:**
- Edificaciones: 25 metros
- Carreteras: 10 metros

**Épocas de poda:**
- Permitida: octubre a febrero
- Prohibida: marzo a septiembre`;

// ============================================
// CAPA 2: Contexto específico según palabras clave
// ============================================
const mensaje = (i.message || "").toLowerCase();
let contextoEspecifico = "";

// 1. INCENDIOS FORESTALES
if (mensaje.match(/incendio|fuego|humo|quemar|conato|llama|foco|térmico|riesgo|alerta|extinción|brigada|infoca|infocam/)) {
  contextoEspecifico += `
=== LEYES PARA INCENDIOS FORESTALES ===
- Ley 43/2003, Artículo 51: Obligación de comunicar inmediatamente cualquier incendio
- Real Decreto 893/2013: Clasificación de riesgos (BAJO/MODERADO/ALTO/EXTREMO)
- Época de peligro alto: 1 junio - 30 septiembre (varía por comunidad)
- Prohibición de quemas agrícolas sin autorización durante época de peligro
- Multas por incendio negligente: desde 100.000€ hasta responsabilidad penal
- Plan INFOCA (Andalucía), INFOCAM (Madrid), INFOCAT (Cataluña) - Planes autonómicos
`;
}

// 2. DRONES
if (mensaje.match(/dron|uav|vuelo|sobrevolar|aéreo|piloto|aeronave|drone/)) {
  contextoEspecifico += `
